class WireTap
  attr_reader :dropped

  def initialize(primary, capacity: 1_000)
    @primary = primary
    @queue   = Thread::SizedQueue.new(capacity)
    @dropped = 0
    @worker  = Thread.new do
      loop do
        begin
          analyze(@queue.pop)   # out-of-band, but GVL-paced
        rescue => e
          warn "wire-tap analyzer error: #{e.class}"
        end
      end
    end
  end

  def call(message)
    begin
      # Marshal round-trip = isolated snapshot; dup would alias nested data
      @queue.push(Marshal.load(Marshal.dump(message)), true)
    rescue ThreadError
      @dropped += 1             # bounded overflow: drop the copy, count it
    end
    @primary.call(message)      # primary gets the original, unchanged
  end

  def close
    @queue.close
    @worker.join
  end

  private

  def analyze(snapshot)
    Analytics.record(snapshot)
  end
end
